INSERT INTO changelog (title, body, created_at) VALUES ('Джері: коротші інструкції', 'Системні інструкції Джері стиснуті втричі (≈16,6k → 5,7k символів): лишились характер і тон, як працювати, куди що записувати (проєкти, стратегія, реклама, продажі, гроші, повідомлення клієнтам) і правила безпеки. Кожна відповідь дешевша і швидша, а важливе не губиться серед деталей. Якщо Джері став робити щось гірше, ніж раніше, — напиши в журнал «Доробити», що саме.', datetime('now'));
